  a=BigInt(a)%n; if(a===0n) return true;
  var x=modpow(a,d,n); if(x===1n||x===n-1n) return true;
  for(var i=1n; i<r; i++){ x=x*x%n; if(x===n-1n) return true; }
  return false; }
